30	/** HIL and splitter inspection share the saved graph lineage and exact historical outputs. */
31	export function HilReport() {
32	  const report = useDataflow((s) => s.report);
33	  const editorRoot = useDataflow((s) => s.root);
34	  const currentRun = useStore(runStore, (s) => s.run);
35	  const snapshotStep = useMemo(
36	    () =>
37	      currentRun && report
38	        ? [...walkBlocks(currentRun.graph)].find(({ block }) => block.id === report.blockId)
39	        : undefined,
40	    [currentRun, report],
41	  );
42	  const run = snapshotStep ? currentRun : null;
43	  const root = run?.graph ?? editorRoot;
44	  const path = snapshotStep?.path ?? report?.path ?? [];
45	  const block = useMemo(() => {
46	    if (!report) return null;
47	    try {
48	      return graphAt(root, path).blocks.find((b) => b.id === report.blockId) ?? null;
49	    } catch {
50	      return null; // its workplace was deleted
51	    }
52	  }, [root, path, report]);
53	
54	  useEffect(() => {
55	    if (report && !block) dataflowStore.getState().closeReport();
56	  }, [report, block]);
57	
58	  if (!report || !block) return null;
59	  // Keyed by block: the selection starts fresh for every report.
60	  return (
61	    <ReportDialog
62	      key={`${run?.id ?? "preview"}:${block.id}`}
63	      root={root}
64	      path={path}
65	      block={block}
66	      run={run}
67	    />
68	  );
69	}
